insert into page_content (key, kind, value) values
  ('home.heroBackground', 'image', 'media-page-home.heroBackground'),
  ('home.philosophyTeaser', 'image', 'media-page-home.philosophyTeaser'),
  ('winery.philosophy', 'image', 'media-page-winery.philosophy'),
  ('winery.vineyard', 'image', 'media-page-winery.vineyard'),
  ('winery.harvest', 'image', 'media-page-winery.harvest'),
  ('winery.cellar', 'image', 'media-page-winery.cellar'),
  ('about.history', 'image', 'media-page-about.history'),
  ('about.today', 'image', 'media-page-about.today'),
  ('about.roberto', 'image', 'media-page-about.roberto'),
  ('visit.openingHoursTitle', 'text', 'Opening Hours'),
  ('visit.openingHoursText', 'text', 'Visits by appointment only — get in touch and we''ll find a time that works. Typically Monday–Saturday, 10:00–17:00.'),
  ('en:home.introTitle', 'text', 'A family winery, made the slow way'),
  ('en:home.introText', 'text', 'For three generations, the Valletti family has tended the same hillside vineyards, working with the seasons rather than against them. Every bottle carries the mark of that patience — and of Roberto Valletti, who still walks the rows every morning.'),
  ('en:winery.openingLine', 'text', 'When family winemaking tradition, academic knowledge and innovation come together, there is an opportunity to create truly exceptional wines.'),
  ('en:winery.philosophyQuote', 'text', 'Great wine is about identity. It is about unlocking the full potential of two interconnected worlds: the terroir and the cellar. Neither can compensate for the other. There are no shortcuts to excellence.'),
  ('en:winery.vineyardTitle', 'text', 'The Vineyard'),
  ('en:winery.vineyardText1', 'text', 'The journey always begins in the vineyard. Producing outstanding wine requires dedication, patience and an uncompromising commitment to creating the best possible conditions for the vines. Every decision, from soil management to canopy management and yield control, is made with one purpose in mind: ensuring that only the finest grapes become part of the final wine.'),
  ('en:winery.vineyardText2', 'text', 'For the Valletti estate, understanding and continuously improving the terroir has always been a fundamental principle. Generations of family experience have been combined with academic knowledge and a willingness to embrace innovation in order to reveal the unique character of each vineyard. The objective has never been to produce wine that simply reflects a grape variety, but to capture the identity of the land itself.'),
  ('en:winery.harvestTitle', 'text', 'The Harvest'),
  ('en:winery.harvestText1', 'text', 'Every year, as August approaches, attention shifts from the vineyard to the cellar. Harvest is one of the most important and demanding periods of the year, where experience, timing and careful planning determine the quality of the vintage.'),
  ('en:winery.harvestText2', 'text', 'There is only a small window in which each grape variety reaches its optimal ripeness. Harvesting too early can result in wines lacking complexity and balance, while harvesting too late may compromise freshness and structure. Every vineyard, and often every individual parcel, is monitored closely to ensure that each grape is picked at precisely the right moment.'),
  ('en:winery.cellarTitle', 'text', 'The Cellar'),
  ('en:winery.cellarText1', 'text', 'Once the grapes arrive at the cellar, the next stage of the journey begins. Each variety, and ultimately each wine, is carefully handled according to its unique characteristics and the style that the Valletti estate wishes to express. From fermentation and extraction to ageing and blending, every decision shapes the experience that will eventually be found in the bottle.'),
  ('en:winery.cellarText2', 'text', 'No two vintages are ever the same. Sunshine, rainfall, temperature fluctuations and countless other natural influences ensure that every harvest presents a new set of opportunities and challenges. Rather than following a rigid formula, Roberto Valletti allows each vintage to guide his decisions. Drawing on generations of family knowledge, supported by academic expertise and a continuous drive to innovate, he adapts every stage of the winemaking process to express the very best of that particular year.'),
  ('en:winery.closingQuote', 'text', 'The cellar is not a place where great wine is created. It is where the potential that has been carefully nurtured in the vineyard is preserved, refined and respectfully expressed. The role of the winemaker is not to change the character of the grapes, but to reveal it.'),
  ('en:winery.closingText', 'text', 'This philosophy has guided the Valletti family for generations. Exceptional wine is never the result of chance. It is the product of tradition, scientific understanding, innovation and relentless attention to detail, from the first work in the vineyard to the moment the wine is poured into the glass. Every bottle is an expression of the Valletti family''s commitment to authenticity, quality and respect for the land that makes it all possible.'),
  ('en:about.historyTitle', 'text', 'How It Started'),
  ('en:about.historyText', 'text', 'In 1958, Roberto''s grandfather, Alessandro Valletti, planted the first rows of Dolcetto on a steep, stony hillside that most of his neighbours considered too difficult to farm. He was wrong about it being difficult — it just required patience. His son Marco expanded the estate in the 1980s, and today Roberto Valletti continues the work, having taken over the cellar in 2005 after studying oenology and working harvests across Italy and France.'),
  ('en:about.todayTitle', 'text', 'Valletti Today'),
  ('en:about.todayText', 'text', 'Today the estate spans a small number of carefully tended hectares across two vineyard sites. We remain a family operation — Roberto in the vineyard and cellar, with his wife Elena managing the estate and welcoming visitors. We produce a limited number of wines each year, all from our own grapes, all made on site.'),
  ('nl:home.introTitle', 'text', 'Een familiewijnhuis, op de langzame manier'),
  ('nl:home.introText', 'text', 'Al drie generaties lang onderhoudt de familie Valletti dezelfde wijngaarden op de heuvel, werkend met de seizoenen in plaats van ertegen. Elke fles draagt het teken van dat geduld — en van Roberto Valletti, die nog elke ochtend door de rijen loopt.'),
  ('nl:winery.openingLine', 'text', 'Wanneer familietraditie in de wijnbouw, academische kennis en innovatie samenkomen, ontstaat de kans om werkelijk uitzonderlijke wijnen te maken.'),
  ('nl:winery.philosophyQuote', 'text', 'Grote wijn draait om identiteit. Het gaat om het volledig benutten van twee onlosmakelijk verbonden werelden: het terroir en de kelder. Het een kan het ander nooit compenseren. Er zijn geen kortere wegen naar uitmuntendheid.'),
  ('nl:winery.vineyardTitle', 'text', 'De Wijngaard'),
  ('nl:winery.vineyardText1', 'text', 'De reis begint altijd in de wijngaard. Het maken van uitzonderlijke wijn vraagt om toewijding, geduld en een niet-aflatende inzet om de best mogelijke omstandigheden voor de wijnstokken te scheppen. Elke beslissing, van bodembeheer tot bladerdakbeheer en opbrengstbeperking, wordt genomen met één doel: ervoor zorgen dat alleen de beste druiven deel gaan uitmaken van de uiteindelijke wijn.'),
  ('nl:winery.vineyardText2', 'text', 'Voor het landgoed Valletti is het begrijpen en voortdurend verbeteren van het terroir altijd een fundamenteel principe geweest. Generaties familie-ervaring zijn gecombineerd met academische kennis en de bereidheid om innovatie te omarmen, om zo het unieke karakter van elke wijngaard te onthullen. Het doel is nooit geweest om een wijn te maken die simpelweg een druivenras weerspiegelt, maar om de identiteit van het land zelf te vangen.'),
  ('nl:winery.harvestTitle', 'text', 'De Oogst'),
  ('nl:winery.harvestText1', 'text', 'Elk jaar, naarmate augustus nadert, verschuift de aandacht van de wijngaard naar de kelder. De oogst is een van de belangrijkste en veeleisendste periodes van het jaar, waarin ervaring, timing en zorgvuldige planning de kwaliteit van de jaargang bepalen.'),
  ('nl:winery.harvestText2', 'text', 'Er is slechts een klein tijdsvenster waarin elk druivenras zijn optimale rijpheid bereikt. Te vroeg oogsten kan leiden tot wijnen die complexiteit en balans missen, terwijl te laat oogsten frisheid en structuur kan aantasten. Elke wijngaard, en vaak elk individueel perceel, wordt nauwlettend gevolgd om ervoor te zorgen dat elke druif op precies het juiste moment wordt geplukt.'),
  ('nl:winery.cellarTitle', 'text', 'De Kelder'),
  ('nl:winery.cellarText1', 'text', 'Zodra de druiven in de kelder aankomen, begint de volgende fase van de reis. Elk ras, en uiteindelijk elke wijn, wordt zorgvuldig behandeld volgens zijn unieke kenmerken en de stijl die het landgoed Valletti wil uitdrukken. Van gisting en extractie tot rijping en assemblage — elke beslissing vormt de ervaring die uiteindelijk in de fles terug te vinden is.'),
  ('nl:winery.cellarText2', 'text', 'Geen twee jaargangen zijn ooit hetzelfde. Zonneschijn, regenval, temperatuurschommelingen en talloze andere natuurlijke invloeden zorgen ervoor dat elke oogst nieuwe kansen en uitdagingen met zich meebrengt. In plaats van een strak stramien te volgen, laat Roberto Valletti elke jaargang zijn beslissingen sturen. Voortbouwend op generaties familiekennis, ondersteund door academische expertise en een voortdurende drang tot innovatie, past hij elke fase van het wijnmaken aan om het beste van dat specifieke jaar tot uitdrukking te brengen.'),
  ('nl:winery.closingQuote', 'text', 'De kelder is niet de plek waar grote wijn wordt gemaakt. Het is de plek waar het potentieel dat zorgvuldig in de wijngaard is gekoesterd, wordt bewaard, verfijnd en met respect tot uitdrukking gebracht. De rol van de wijnmaker is niet om het karakter van de druiven te veranderen, maar om het te onthullen.'),
  ('nl:winery.closingText', 'text', 'Deze filosofie leidt de familie Valletti al generaties lang. Uitzonderlijke wijn is nooit het resultaat van toeval. Het is het product van traditie, wetenschappelijk inzicht, innovatie en een niet-aflatende aandacht voor detail, van het eerste werk in de wijngaard tot het moment waarop de wijn in het glas wordt geschonken. Elke fles is een uiting van de toewijding van de familie Valletti aan authenticiteit, kwaliteit en respect voor het land dat dit alles mogelijk maakt.'),
  ('nl:about.historyTitle', 'text', 'Hoe Het Begon'),
  ('nl:about.historyText', 'text', 'In 1958 plantte Roberto''s grootvader, Alessandro Valletti, de eerste rijen Dolcetto op een steile, stenige heuvel die de meeste van zijn buren te lastig vonden om te bewerken. Hij had ongelijk over de moeilijkheid — het vroeg alleen om geduld. Zijn zoon Marco breidde het landgoed in de jaren tachtig uit, en vandaag zet Roberto Valletti het werk voort. Hij nam de kelder in 2005 over, na een opleiding oenologie en oogstwerk in heel Italië en Frankrijk.'),
  ('nl:about.todayTitle', 'text', 'Valletti Vandaag'),
  ('nl:about.todayText', 'text', 'Tegenwoordig omvat het landgoed een klein aantal zorgvuldig onderhouden hectares op twee wijngaardlocaties. Wij blijven een familiebedrijf — Roberto in de wijngaard en de kelder, met zijn vrouw Elena die het landgoed beheert en bezoekers verwelkomt. Wij produceren elk jaar een beperkt aantal wijnen, allemaal van eigen druiven, allemaal gemaakt op het landgoed zelf.'),
  ('de:home.introTitle', 'text', 'Ein Familienweingut, auf die langsame Art'),
  ('de:home.introText', 'text', 'Seit drei Generationen pflegt die Familie Valletti dieselben Hügelweinberge und arbeitet mit den Jahreszeiten statt gegen sie. Jede Flasche trägt das Zeichen dieser Geduld — und das von Roberto Valletti, der noch jeden Morgen durch die Rebzeilen geht.'),
  ('de:winery.openingLine', 'text', 'Wenn familiäre Weinbautradition, akademisches Wissen und Innovation zusammenkommen, entsteht die Möglichkeit, wahrhaft außergewöhnliche Weine zu schaffen.'),
  ('de:winery.philosophyQuote', 'text', 'Großer Wein handelt von Identität. Es geht darum, das volle Potenzial zweier miteinander verbundener Welten zu erschließen: das Terroir und den Keller. Keines kann das andere ersetzen. Es gibt keine Abkürzungen zur Exzellenz.'),
  ('de:winery.vineyardTitle', 'text', 'Der Weinberg'),
  ('de:winery.vineyardText1', 'text', 'Die Reise beginnt immer im Weinberg. Herausragenden Wein hervorzubringen erfordert Hingabe, Geduld und ein kompromissloses Engagement, die bestmöglichen Bedingungen für die Reben zu schaffen. Jede Entscheidung, von der Bodenbewirtschaftung über das Laubwandmanagement bis zur Ertragsregulierung, wird mit einem einzigen Ziel getroffen: sicherzustellen, dass nur die besten Trauben Teil des fertigen Weins werden.'),
  ('de:winery.vineyardText2', 'text', 'Für das Weingut Valletti war das Verständnis und die kontinuierliche Verbesserung des Terroirs stets ein grundlegendes Prinzip. Generationen familiärer Erfahrung wurden mit akademischem Wissen und der Bereitschaft zur Innovation verbunden, um den einzigartigen Charakter jedes Weinbergs zu offenbaren. Das Ziel war nie, einen Wein zu erzeugen, der lediglich eine Rebsorte widerspiegelt, sondern die Identität des Landes selbst einzufangen.'),
  ('de:winery.harvestTitle', 'text', 'Die Ernte'),
  ('de:winery.harvestText1', 'text', 'Jedes Jahr, wenn sich der August nähert, verlagert sich die Aufmerksamkeit vom Weinberg zum Keller. Die Ernte ist eine der wichtigsten und anspruchsvollsten Perioden des Jahres, in der Erfahrung, Timing und sorgfältige Planung die Qualität des Jahrgangs bestimmen.'),
  ('de:winery.harvestText2', 'text', 'Es gibt nur ein kleines Zeitfenster, in dem jede Rebsorte ihre optimale Reife erreicht. Eine zu frühe Lese kann zu Weinen führen, denen es an Komplexität und Balance mangelt, während eine zu späte Lese Frische und Struktur beeinträchtigen kann. Jeder Weinberg, und oft jede einzelne Parzelle, wird genau überwacht, damit jede Traube exakt zum richtigen Zeitpunkt gelesen wird.'),
  ('de:winery.cellarTitle', 'text', 'Der Keller'),
  ('de:winery.cellarText1', 'text', 'Sobald die Trauben im Keller ankommen, beginnt die nächste Etappe der Reise. Jede Rebsorte, und letztlich jeder Wein, wird sorgfältig entsprechend ihren einzigartigen Eigenschaften und dem Stil behandelt, den das Weingut Valletti zum Ausdruck bringen möchte. Von Gärung und Extraktion bis zu Ausbau und Verschnitt prägt jede Entscheidung das Erlebnis, das später in der Flasche zu finden sein wird.'),
  ('de:winery.cellarText2', 'text', 'Kein Jahrgang gleicht dem anderen. Sonnenschein, Niederschlag, Temperaturschwankungen und unzählige weitere natürliche Einflüsse sorgen dafür, dass jede Ernte neue Chancen und Herausforderungen mit sich bringt. Anstatt einer starren Formel zu folgen, lässt Roberto Valletti sich von jedem Jahrgang leiten. Gestützt auf Generationen von Familienwissen, akademische Expertise und einen beständigen Innovationsdrang passt er jede Phase der Weinbereitung an, um das Beste aus diesem besonderen Jahr herauszuholen.'),
  ('de:winery.closingQuote', 'text', 'Der Keller ist nicht der Ort, an dem großer Wein entsteht. Er ist der Ort, an dem das im Weinberg sorgfältig gehegte Potenzial bewahrt, verfeinert und respektvoll zum Ausdruck gebracht wird. Die Aufgabe des Winzers ist es nicht, den Charakter der Trauben zu verändern, sondern ihn zu offenbaren.'),
  ('de:winery.closingText', 'text', 'Diese Philosophie leitet die Familie Valletti seit Generationen. Außergewöhnlicher Wein ist nie das Ergebnis von Zufall. Er ist das Produkt von Tradition, wissenschaftlichem Verständnis, Innovation und unermüdlicher Aufmerksamkeit für Details — von der ersten Arbeit im Weinberg bis zu dem Moment, in dem der Wein ins Glas gegossen wird. Jede Flasche ist Ausdruck des Engagements der Familie Valletti für Authentizität, Qualität und Respekt vor dem Land, das all dies erst möglich macht.'),
  ('de:about.historyTitle', 'text', 'Wie Alles Begann'),
  ('de:about.historyText', 'text', '1958 pflanzte Robertos Großvater, Alessandro Valletti, die ersten Reihen Dolcetto auf einem steilen, steinigen Hügel, den die meisten seiner Nachbarn für zu schwierig zu bewirtschaften hielten. Er irrte sich bezüglich der Schwierigkeit — es erforderte nur Geduld. Sein Sohn Marco erweiterte das Weingut in den 1980er Jahren, und heute führt Roberto Valletti die Arbeit fort. Er übernahm den Keller 2005, nach einem Önologiestudium und Erntearbeit in ganz Italien und Frankreich.'),
  ('de:about.todayTitle', 'text', 'Valletti Heute'),
  ('de:about.todayText', 'text', 'Heute umfasst das Weingut eine kleine Anzahl sorgfältig gepflegter Hektar an zwei Weinbergstandorten. Wir bleiben ein Familienbetrieb — Roberto im Weinberg und im Keller, seine Frau Elena leitet das Anwesen und empfängt Besucher. Wir produzieren jedes Jahr eine begrenzte Anzahl von Weinen, alle aus eigenen Trauben, alle vor Ort hergestellt.'),
  ('fr:home.introTitle', 'text', 'Un domaine familial, à l''ancienne'),
  ('fr:home.introText', 'text', 'Depuis trois générations, la famille Valletti entretient les mêmes vignobles de coteau, travaillant avec les saisons plutôt que contre elles. Chaque bouteille porte la marque de cette patience — et celle de Roberto Valletti, qui parcourt encore les rangs chaque matin.'),
  ('fr:winery.openingLine', 'text', 'Lorsque la tradition viticole familiale, le savoir académique et l''innovation se rencontrent, naît la possibilité de créer des vins véritablement exceptionnels.'),
  ('fr:winery.philosophyQuote', 'text', 'Un grand vin est avant tout une question d''identité. Il s''agit de révéler tout le potentiel de deux mondes indissociables : le terroir et le chai. L''un ne peut jamais compenser l''autre. Il n''existe aucun raccourci vers l''excellence.'),
  ('fr:winery.vineyardTitle', 'text', 'Le Vignoble'),
  ('fr:winery.vineyardText1', 'text', 'Le voyage commence toujours dans le vignoble. Élaborer un vin d''exception exige dévouement, patience et un engagement sans compromis à créer les meilleures conditions possibles pour la vigne. Chaque décision, de la gestion des sols à la conduite du feuillage en passant par le contrôle des rendements, obéit à un seul objectif : garantir que seuls les plus beaux raisins entrent dans la composition du vin final.'),
  ('fr:winery.vineyardText2', 'text', 'Pour le domaine Valletti, comprendre et sans cesse perfectionner le terroir a toujours été un principe fondamental. Des générations d''expérience familiale se sont conjuguées au savoir académique et à une volonté d''innover pour révéler le caractère unique de chaque parcelle. L''objectif n''a jamais été de produire un vin qui se contente de refléter un cépage, mais de capturer l''identité même de la terre.'),
  ('fr:winery.harvestTitle', 'text', 'Les Vendanges'),
  ('fr:winery.harvestText1', 'text', 'Chaque année, à l''approche du mois d''août, l''attention se déplace du vignoble vers le chai. Les vendanges comptent parmi les périodes les plus importantes et les plus exigeantes de l''année, où l''expérience, le choix du moment et une planification minutieuse déterminent la qualité du millésime.'),
  ('fr:winery.harvestText2', 'text', 'Chaque cépage n''atteint sa maturité optimale que durant une fenêtre très courte. Vendanger trop tôt peut donner des vins manquant de complexité et d''équilibre, tandis que vendanger trop tard peut compromettre leur fraîcheur et leur structure. Chaque vignoble, et souvent chaque parcelle, est surveillé de près afin que chaque grappe soit cueillie exactement au bon moment.'),
  ('fr:winery.cellarTitle', 'text', 'Le Chai'),
  ('fr:winery.cellarText1', 'text', 'Dès l''arrivée du raisin au chai, une nouvelle étape du voyage commence. Chaque cépage, et finalement chaque vin, est traité avec soin selon ses caractéristiques propres et le style que le domaine Valletti souhaite exprimer. De la fermentation à l''extraction, en passant par l''élevage et l''assemblage, chaque décision façonne l''expérience que l''on retrouvera dans la bouteille.'),
  ('fr:winery.cellarText2', 'text', 'Aucun millésime ne ressemble à un autre. Le soleil, les précipitations, les variations de température et d''innombrables autres influences naturelles font de chaque vendange un nouvel ensemble d''opportunités et de défis. Plutôt que de suivre une formule rigide, Roberto Valletti laisse chaque millésime guider ses décisions. Fort de générations de savoir familial, soutenu par une expertise académique et une volonté constante d''innover, il adapte chaque étape de la vinification pour exprimer le meilleur de cette année particulière.'),
  ('fr:winery.closingQuote', 'text', 'Le chai n''est pas l''endroit où naît un grand vin. C''est l''endroit où le potentiel patiemment cultivé dans le vignoble est préservé, affiné et exprimé avec respect. Le rôle du vinificateur n''est pas de transformer le caractère du raisin, mais de le révéler.'),
  ('fr:winery.closingText', 'text', 'Cette philosophie guide la famille Valletti depuis des générations. Un vin d''exception n''est jamais le fruit du hasard. Il est le produit de la tradition, de la compréhension scientifique, de l''innovation et d''une attention constante portée aux détails, du premier travail dans la vigne jusqu''au moment où le vin est versé dans le verre. Chaque bouteille exprime l''engagement de la famille Valletti envers l''authenticité, la qualité et le respect de la terre qui rend tout cela possible.'),
  ('fr:about.historyTitle', 'text', 'Les Débuts'),
  ('fr:about.historyText', 'text', 'En 1958, le grand-père de Roberto, Alessandro Valletti, planta les premiers rangs de Dolcetto sur une colline pentue et caillouteuse que la plupart de ses voisins jugeaient trop difficile à cultiver. Il avait tort sur la difficulté — cela ne demandait que de la patience. Son fils Marco agrandit le domaine dans les années 1980, et aujourd''hui Roberto Valletti poursuit ce travail, ayant repris le chai en 2005 après des études d''œnologie et des vendanges à travers l''Italie et la France.'),
  ('fr:about.todayTitle', 'text', 'Valletti Aujourd''hui'),
  ('fr:about.todayText', 'text', 'Aujourd''hui, le domaine s''étend sur un petit nombre d''hectares soigneusement entretenus, répartis sur deux sites viticoles. Nous restons une exploitation familiale — Roberto à la vigne et au chai, son épouse Elena gérant le domaine et accueillant les visiteurs. Nous produisons chaque année un nombre limité de vins, tous issus de nos propres raisins, tous élaborés sur place.'),
  ('it:home.introTitle', 'text', 'Una cantina di famiglia, con calma'),
  ('it:home.introText', 'text', 'Da tre generazioni, la famiglia Valletti si prende cura degli stessi vigneti collinari, lavorando insieme alle stagioni e non contro di esse. Ogni bottiglia porta il segno di questa pazienza — e quello di Roberto Valletti, che ogni mattina cammina ancora tra i filari.'),
  ('it:winery.openingLine', 'text', 'Quando la tradizione familiare della vinificazione, la conoscenza accademica e l''innovazione si incontrano, nasce l''opportunità di creare vini davvero eccezionali.'),
  ('it:winery.philosophyQuote', 'text', 'Il grande vino è questione di identità. Significa cogliere appieno il potenziale di due mondi interconnessi: il terroir e la cantina. Nessuno dei due può sopperire all''altro. Non esistono scorciatoie verso l''eccellenza.'),
  ('it:winery.vineyardTitle', 'text', 'Il Vigneto'),
  ('it:winery.vineyardText1', 'text', 'Il percorso inizia sempre in vigna. Produrre un vino straordinario richiede dedizione, pazienza e un impegno assoluto nel creare le migliori condizioni possibili per le viti. Ogni decisione, dalla gestione del suolo alla gestione della chioma fino al controllo delle rese, viene presa con un solo obiettivo: garantire che solo le uve migliori diventino parte del vino finale.'),
  ('it:winery.vineyardText2', 'text', 'Per l''azienda Valletti, comprendere e migliorare costantemente il terroir è sempre stato un principio fondamentale. Generazioni di esperienza familiare si sono unite alla conoscenza accademica e alla volontà di abbracciare l''innovazione, per rivelare il carattere unico di ogni vigneto. L''obiettivo non è mai stato produrre un vino che si limiti a rispecchiare un vitigno, ma catturare l''identità stessa della terra.'),
  ('it:winery.harvestTitle', 'text', 'La Vendemmia'),
  ('it:winery.harvestText1', 'text', 'Ogni anno, con l''avvicinarsi di agosto, l''attenzione si sposta dal vigneto alla cantina. La vendemmia è uno dei periodi più importanti e impegnativi dell''anno, in cui esperienza, tempismo e pianificazione accurata determinano la qualità dell''annata.'),
  ('it:winery.harvestText2', 'text', 'Esiste solo una piccola finestra temporale in cui ogni vitigno raggiunge la maturazione ottimale. Vendemmiare troppo presto può dare vini privi di complessità ed equilibrio, mentre vendemmiare troppo tardi può comprometterne la freschezza e la struttura. Ogni vigneto, e spesso ogni singola particella, viene monitorato attentamente affinché ogni grappolo venga raccolto esattamente al momento giusto.'),
  ('it:winery.cellarTitle', 'text', 'La Cantina'),
  ('it:winery.cellarText1', 'text', 'Non appena l''uva arriva in cantina, inizia la fase successiva del percorso. Ogni vitigno, e in ultima analisi ogni vino, viene trattato con cura secondo le sue caratteristiche uniche e lo stile che l''azienda Valletti desidera esprimere. Dalla fermentazione all''estrazione, fino all''affinamento e all''assemblaggio, ogni decisione plasma l''esperienza che si ritroverà infine nel bicchiere.'),
  ('it:winery.cellarText2', 'text', 'Non esistono due annate uguali. Sole, piogge, sbalzi di temperatura e innumerevoli altri fattori naturali fanno sì che ogni vendemmia porti con sé nuove opportunità e nuove sfide. Anziché seguire uno schema rigido, Roberto Valletti lascia che sia ogni annata a guidare le sue scelte. Forte di generazioni di conoscenza familiare, sostenuto da competenza accademica e da una costante spinta all''innovazione, adatta ogni fase della vinificazione per esprimere il meglio di quell''annata particolare.'),
  ('it:winery.closingQuote', 'text', 'La cantina non è il luogo dove nasce il grande vino. È il luogo dove il potenziale coltivato con cura in vigna viene preservato, affinato ed espresso con rispetto. Il compito dell''enologo non è cambiare il carattere dell''uva, ma rivelarlo.'),
  ('it:winery.closingText', 'text', 'Questa filosofia guida la famiglia Valletti da generazioni. Il vino eccezionale non è mai frutto del caso. È il prodotto della tradizione, della conoscenza scientifica, dell''innovazione e di un''attenzione instancabile ai dettagli, dal primo lavoro in vigna fino al momento in cui il vino viene versato nel bicchiere. Ogni bottiglia è espressione dell''impegno della famiglia Valletti per l''autenticità, la qualità e il rispetto della terra che rende tutto questo possibile.'),
  ('it:about.historyTitle', 'text', 'Come è Iniziata'),
  ('it:about.historyText', 'text', 'Nel 1958, il nonno di Roberto, Alessandro Valletti, piantò i primi filari di Dolcetto su una collina ripida e sassosa che la maggior parte dei vicini considerava troppo difficile da coltivare. Si sbagliava sulla difficoltà — serviva solo pazienza. Suo figlio Marco ampliò la tenuta negli anni ''80 e oggi Roberto Valletti continua il lavoro, avendo preso in mano la cantina nel 2005 dopo aver studiato enologia e fatto vendemmie in giro per l''Italia e la Francia.'),
  ('it:about.todayTitle', 'text', 'Valletti Oggi'),
  ('it:about.todayText', 'text', 'Oggi la tenuta si estende su un numero contenuto di ettari curati con attenzione, su due appezzamenti. Restiamo un''azienda familiare — Roberto in vigna e in cantina, con la moglie Elena che gestisce la tenuta e accoglie i visitatori. Produciamo ogni anno un numero limitato di vini, tutti dalle nostre uve, tutti realizzati in azienda.')
